import json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parent
versions=json.loads((ROOT/'runtime-versions.json').read_text())
results=[json.loads(x) for x in (ROOT/'results.jsonl').read_text().splitlines()] if (ROOT/'results.jsonl').exists() else []
latest={r['seed']:r for r in results if r['frames']==49 and r['seed'] in (42,43,44) and r['status'] in ('execution_success','finished') and r['sampler_executed']}
rows=list(latest.values())
def gib(x): return f'{x/1024**3:.2f}' if isinstance(x,(int,float)) else 'not measured'
lines=['# LTX-Video 2B v0.9.5 — actual local results','', 'Device: MacBook Pro M4 Pro, 16-core GPU, 24 GB unified memory; macOS 27.0.1.','',f'Runtime: ComfyUI 0.43.0; PyTorch {versions["torch"]}; Python {versions["python"]}; MPS.','', 'Workflow: official v0.9.5 text-to-video workflow; 512×320, batch 1, 25 conditioning/playback FPS, 30 steps, guidance 3, res_multistep. Scheduler: max_shift 2.05, base_shift 0.95, stretch true, terminal 0.1. No interpolation or upscale. WebP and WebM are written by native nodes.','', 'Precision: checkpoint storage BF16 (verified from its safetensors header). Encoder and actual execution dtypes are reported in the server log; storage and compute precision must not be conflated.','', '## Actual runs','', '| Run | Frames | Seed | Actual time (s) | Generated frames/s | Status | Power | Sampled max RSS (GiB) | Sampled max MPS driver (GiB) | System swap before → after (GiB) |','|---|---:|---:|---:|---:|---|---|---:|---:|---|']
for r in results:
    m=r['memory']; lines.append(f'| {r["label"]} | {r["frames"]} | {r["seed"]} | {r["elapsed_client_s"]:.3f} | {r["generated_frames_per_second"]:.4f} | {r["status"]} | {r["conditions"]} | {gib(m.get("sampled_max_rss_bytes"))} | {gib(m.get("sampled_max_mps_driver_bytes"))} | {gib(r["before"]["swap_bytes"])} → {gib(r["after"]["swap_bytes"])} |')
if len(rows)==3:
    mean=statistics.mean(r['elapsed_client_s'] for r in rows)
    lines+=['',f'Mean of seeds 42, 43, 44: **{mean:.3f} s** for 49 frames. Aggregate generation speed: {49/mean:.4f} frames/s. Playback duration is 1.96 seconds; playback FPS is unrelated to generation speed.']
else: lines+=['','Three successful 49-frame benchmark runs are not yet complete; no three-run mean is claimed.']
lines+=['','## Conditions and limits','','Battery runs are explicitly labelled nonstandard. They do not satisfy the AC-power, Low Power Mode off benchmark conditions in the handoff. Per-run power settings are saved in the result JSON. Other user applications remain running; system swap changes are not attributed exclusively to ComfyUI. Initial system swap was already about 5.4 GiB.','','Time is client submission to server execution success. Cold execution includes uncached prompt encoding/model loading. Warm runs use the same classic node cache and default ComfyUI model residency/offloading; cached node IDs and proof of sampler execution are recorded per run. Time includes sampling, VAE decode, and both native output writes, and excludes setup/downloads and later verification.','','Memory is sampled at 1 Hz inside the ComfyUI process. Values are sampled maxima, not true allocator peaks. RSS and MPS allocations overlap and must not be added. Unified memory is not separate NVIDIA VRAM.','','The server used --offline, offline library flags, disabled paid/custom nodes, and a Python socket audit guard blocking non-loopback connections. This does not disable internet for other applications.','','Browser visual inspection was not permitted by the browser access gate. Backend behavior is verified through the local API; output media is verified separately.','','## Reproduction and evidence','','See README.md for commands and locations. See requirements-lock.txt, machine.json, runtime-versions.json, model-integrity.json, workflows/, logs/, output-verification.json, and output/. Output and benchmark observations are actual local measurements; no M3 Max or RTX 3050 results are substituted.','','## Visual assessment','','See visual-assessment.md after inspection. This is one prompt and short clips; it is not a general model-quality evaluation.']
(ROOT/'RESULTS.md').write_text('\n'.join(lines)+'\n')
print(ROOT/'RESULTS.md')
